/**
 * Self-Hosted Lightweight GSAP-Compatible Web Animations Engine (60fps GPU-Accelerated)
 * Guarantees smooth `gsap.fromTo()` and `gsap.to()` choreography even in offline/sandboxed
 * environments without relying on external CDNs.
 */
(function (global) {
  'use strict';
  if (global.gsap) return;

  const EASE_MAP = {
    'power2.out': 'cubic-bezier(0.22, 1, 0.36, 1)',
    'power3.out': 'cubic-bezier(0.16, 1, 0.3, 1)',
    'sine.inOut': 'cubic-bezier(0.37, 0, 0.63, 1)',
    'linear': 'linear'
  };

  function toArray(targets) {
    if (!targets) return [];
    if (typeof targets === 'string') return Array.from(document.querySelectorAll(targets));
    if (targets instanceof Element) return [targets];
    return Array.from(targets);
  }

  function buildKeyframe(vars) {
    const kf = {};
    const transforms = [];
    if (typeof vars.x === 'number') transforms.push(`translateX(${vars.x}px)`);
    if (typeof vars.y === 'number') transforms.push(`translateY(${vars.y}px)`);
    if (typeof vars.scale === 'number') transforms.push(`scale(${vars.scale})`);
    if (transforms.length > 0) kf.transform = transforms.join(' ');
    if (typeof vars.opacity === 'number') kf.opacity = vars.opacity;
    return kf;
  }

  global.gsap = {
    fromTo(targets, fromVars, toVars) {
      const els = toArray(targets);
      const duration = ((toVars && toVars.duration) || 0.45) * 1000;
      const stagger = ((toVars && toVars.stagger) || 0) * 1000;
      const easing = EASE_MAP[(toVars && toVars.ease) || 'power3.out'] || EASE_MAP['power3.out'];

      els.forEach((el, idx) => {
        if (!el || typeof el.animate !== 'function') return;
        el.animate([buildKeyframe(fromVars || {}), buildKeyframe(toVars || {})], {
          duration,
          delay: idx * stagger,
          easing,
          fill: 'both'
        });
      });
    },
    to(targets, toVars) {
      const els = toArray(targets);
      const duration = ((toVars && toVars.duration) || 0.45) * 1000;
      const easing = EASE_MAP[(toVars && toVars.ease) || 'sine.inOut'] || 'ease-in-out';
      const iterations = toVars && toVars.repeat === -1 ? Infinity : 1;
      const direction = toVars && toVars.yoyo ? 'alternate' : 'normal';

      els.forEach((el) => {
        if (!el || typeof el.animate !== 'function') return;
        el.animate([{}, buildKeyframe(toVars || {})], {
          duration,
          easing,
          iterations,
          direction,
          fill: 'both'
        });
      });
    }
  };
})(window);
